class Solution {
public:
    vector<int> closestDivisors(int num) {
        vector<int> best = {1, num + 1};
        int bestDiff = num;
        for (int t : {num + 1, num + 2}) {
            int s = (int)sqrt((double)t);
            while ((long long)(s + 1) * (s + 1) <= t) s++;
            for (int i = s; i >= 1; i--) {
                if (t % i == 0) {
                    int j = t / i;
                    if (j - i < bestDiff) {
                        bestDiff = j - i;
                        best = {i, j};
                    }
                    break;
                }
            }
        }
        return best;
    }
};
